package com.spendwise.auth; import jakarta.persistence.*;
@Entity @Table(name="app_users") public class AppUser{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false,length=80) private String name;@Column(nullable=false,length=254,unique=true) private String email;@Column(nullable=false,length=100) private String passwordHash;protected AppUser(){}public AppUser(String n,String e,String p){name=n;email=e;passwordHash=p;}public Long getId(){return id;}public String getName(){return name;}public String getEmail(){return email;}public String getPasswordHash(){return passwordHash;}}